// Modelo de juguete: una conexión, una ronda por cada RTT.
// La red "aguanta" 50 segmentos en vuelo (tubo más cola). Si cwnd pasa de 50, hay pérdida.
const CAPACIDAD = 50;
let cwnd = 10;          // ventana inicial: 10 segmentos
let ssthresh = Infinity; // al principio no hay umbral
const historia = [];
for (let rtt = 0; rtt < 40; rtt++) {
  historia.push(cwnd);
  if (cwnd > CAPACIDAD) {
    ssthresh = Math.floor(cwnd / 2);   // multiplicative decrease
    cwnd = ssthresh;
  } else if (cwnd < ssthresh) {
    cwnd = cwnd * 2;                   // slow start: se duplica por RTT
  } else {
    cwnd = cwnd + 1;                   // evitar congestión: +1 por RTT
  }
}
console.log('cwnd en cada RTT (segmentos):');
console.log(historia.join(' '));
const pico = Math.max(...historia.slice(5));
console.log('pico tras el arranque:', pico, '| después de la pérdida baja a', Math.floor(pico / 2));

// ¿Cuántos RTT hacen falta para entregar un archivo chico, si todo anda perfecto?
// Modelo simple: el saludo de tres vías cuesta 1 RTT y después cada ronda envía cwnd segmentos.
const MSS = 1448;
function rondas(bytes, iw = 10) {
  let faltan = Math.ceil(bytes / MSS), cwnd = iw, n = 0;
  while (faltan > 0) { faltan -= cwnd; cwnd *= 2; n++; }
  return n;
}
for (const kb of [15, 50, 200, 1000]) {
  const r = rondas(kb * 1000);
  const rtt = 0.150; // 150 ms: ejemplo inventado de un servidor lejano
  console.log(`${String(kb).padStart(6)} KB: ${r} rondas + 1 del saludo = ${r + 1} RTT = ${((r + 1) * rtt).toFixed(2)} s`);
}
